#define pi acos(-1.)
#define rad pi / 180.
#define gold (sqrt(5.) - 1.) / 2.

#define t54 tan(54. * rad)
#define t18 tan(18. * rad)


#define cos1 cos(36. * rad)
#define sin1 sin(36. * rad)
#define cos2 cos(72. * rad)
#define sin2 sin(72. * rad)

#define rot0 mat2(-1, 0, 0, 1)
#define rot1 mat2(-cos1, -sin1,  sin1, -cos1)
#define rot2 mat2(-cos1,  sin1, -sin1, -cos1)
#define rot3 mat2(-cos2, -sin2,  sin2, -cos2)
#define rot4 mat2( cos2,  sin2,  sin2, -cos2)

// Rhombus distance?
// https://www.shadertoy.com/view/XdXcRB
float border(vec2 q, int type) {
    float ya = t54 * q.y;
    float yb = t18 * q.y;
    float d = 

    type < 2 
        ? min(
              1. - 
              (q.x + ya) * gold, 
              (q.x - ya) * gold
          )

        : min(
              q.x - yb, 
              gold - q.x - yb
          );

    return min(1., d * 25.);
}


float curves(vec2 q, int type){
    float d;
        if(type < 2) d = abs(sqrt(1. - dot(q, q)) - .6);
        else q.x -= .618, d = abs(sqrt(dot(q, q)) * 1.3 - .27);

    return smoothstep(14. / iResolution.y, .0, d - .07) * .7;
}

#define navy vec4(0, 0, .4, 0)
#define yellow vec4(.8, .7, .2, 0)
#define pink vec4(.8, .1, .4, 0)
#define red vec4(1, 0, 0, 0)
#define blue vec4(0, 0, 1, 0)

vec4 getColor(vec2 q, int type) {
    vec4   // alb
#if 1
        o = type < 2 
                ? blue : yellow;

#else
        o = type == 0 
                ? navy :
            type == 1 
                ? pink :
            type == 2    
                ? yellow : 
            type == 3    
                ? blue : red;
#endif

        o += (1. - o) * curves(q, type);  // pattern
        o *= border(q, type);             // border

    return o;
}

int penrose(inout vec2 q) {
    int type, N = 9;
    float a, b, c;

    //a = .5 / cos(36. * rad);
    //b = (1. + a) * .5;
    //c = tan(36. * rad) * b;

    a = gold;
    b = (1. + gold) / 2.;
    c = sin(36. * rad);

    mat2 m;
    for(int k; k < N; k++) {
        if(type < 2) {
            m = rot1;
            if(t54 * q.y + q.x < 1.) 
                q.x -= 1.,
                m = rot0,
                type = 1 - type;

            else if(t18 * q.y + q.x < 1.) 
                q -= vec2(b, c),
                m = rot2,
                type = 3 - type;

            else
                q.x -= a + 1.;
        }

        else {
            m = rot3;

            if(t54 * q.y - q.x > 0.) 
                m = rot4,
                type -= 2;

            else 
                q.x -= a;
        }

        q /= gold; 
        q = m * q;
    }

    return type;
}

void mainImage(out vec4 o, vec2 u) {
    float t = cos(iTime * .1);
    vec2 r = iResolution.xy;
    u = .08 * (u - r / 2.) / r.y
           + vec2(.7 + .6 * pow(abs(t), 4.) * sign(t), tanh(cos(iTime * .3) * 5.) * .04 + .1);
           ;

    int type = penrose(u);
    o = getColor(u, type);
}
